{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C42"],
      "claim": "Valdecoxib, a primary sulfonamide-containing drug, has an absolute oral bioavailability of about 83% in humans, demonstrating that a sulfonamide group and polar functionality do not preclude high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Fasudil, which contains a sulfonyl piperazine and polar heteroaromatic features, has an absolute oral bioavailability of 69% in humans, supporting high oral bioavailability for sulfonamide-like polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Sildenafil, a sulfonamide-containing drug with moderate polarity, has an absolute oral bioavailability of about 40% in adults, which is well above the 20% threshold and supports a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Amrinone, a small polar heteroaromatic molecule, has an oral bioavailability of 90-95% in healthy subjects, showing that small polar molecules can be efficiently absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Fenfluramine, a small moderately polar molecule, has an oral bioavailability of 61-69% in humans, providing additional evidence that small polar drugs commonly exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small polar sulfonamide-containing benzothiadiazine. Although the physicochemical prior raises absorption concerns, multiple high-transfer experimental analogues with sulfonamide, sulfonyl, or small polar heteroaromatic structures show oral bioavailability well above 20% (40-95%). No affirmative experimental evidence supports F < 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for the query molecule itself.",
    "The analogues are not exact structural matches, so transferability relies on shared polar/sulfonamide features rather than identical scaffolds.",
    "Possible active transport, efflux, or first-pass metabolism specific to the query is not directly captured by the available evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

